button {
    background: linear-gradient(to bottom, #3c3c3c 0%, #323233 100%);
    border: 1px solid #464647;
    border-radius: 4px;
    padding: 6px 16px;
    color: #cccccc;
    font-size: 0.875rem;
    font-weight: 500;
