(function() {
    const modeSegmented = document.getElementById('modeSegmented');
    if (!modeSegmented) return;

    const buttons = modeSegmented.querySelectorAll('button');
    let currentMode = 'cutoff'; // default

    // Get current mode from hidden select if it exists, or use default
    const hiddenSelect = document.getElementById('mode');
    if (hiddenSelect) {
        currentMode = hiddenSelect.value;
    }

    // Set active button based on current mode
    buttons.forEach(btn => {
        if (btn.dataset.mode === currentMode) {
            btn.classList.add('active');
        }
        btn.addEventListener('click', function() {
            buttons.forEach(b => b.classList.remove('active'));
            this.classList.add('active');
            currentMode = this.dataset.mode;

            // Update hidden select if it exists
            if (hiddenSelect) {
                hiddenSelect.value = currentMode;
                hiddenSelect.dispatchEvent(new Event('change'));
            } else {
                // Trigger reflow directly
                if (typeof autoReflow === 'function') {
                    autoReflow();
                }
            }
        });
    });

    // Create a hidden select for compatibility with existing code
    if (!hiddenSelect) {
        const hidden = document.createElement('select');
        hidden.id = 'mode';
        hidden.style.display = 'none';
        hidden.innerHTML = '<option value="cutoff">Absolute cutoff</option><option value="edgeProtruding">Edge-protruding</option><option value="justifyHyphenCut">Justified (hyphenated cutoffs)</option><option value="justifySpaces">Justified (adds spaces)</option>';
        hidden.value = currentMode;
        modeSegmented.parentElement.appendChild(hidden);

        // Sync segmented control with hidden select changes
        hidden.addEventListener('change', function() {
            buttons.forEach(btn => {
                btn.classList.toggle('active', btn.dataset.mode === this.value);
            });
        });
    }
})();

